import { Component } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-forgot-password',
  templateUrl: './forgot-password.component.html',
  styleUrls: ['./forgot-password.component.scss']
})
export class ForgotPasswordComponent {
  email: string = '';
  message: string = '';

  constructor(private http: HttpClient) {}

  onSubmit() {
    if (this.email) {
      this.http.post<any>('http://localhost:8080/api/auth/forgot-password', { email: this.email })
        .subscribe({
          next: (response) => {
            this.message = response.message || 'Reset link sent successfully!';
          },
          error: (error) => {
            this.message = error.error.message || 'Something went wrong!';
          }
        });
    }
  }
}
<div class="d-flex justify-content-center align-items-center vh-100 bg-light">
  <div class="card shadow p-4" style="width: 25rem;">
    <h4 class="card-title text-center mb-4">Forgot Password</h4>
    <form (ngSubmit)="onSubmit()" #forgotForm="ngForm">
      <div class="mb-3">
        <label for="email" class="form-label">Enter your email</label>
        <input
          type="email"
          id="email"
          name="email"
          class="form-control"
          required
          [(ngModel)]="email"
        />
      </div>
      <button type="submit" class="btn btn-primary w-100">Send Reset Link</button>
    </form>

    <div *ngIf="message" class="alert alert-info mt-3 text-center">
      {{ message }}
    </div>
  </div>
</div>
